function drawArceusCreatorGod(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.0;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.04 * breathSin;
  const sX = 1.0 - 0.02 * breathSin;
  const by = -Math.abs(breathSin) * 3.5;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 44, 28 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Thánh Luân Hoàng Kim
  ctx.strokeStyle = '#facc15';
  ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.arc(0, by + 10, 18, 0, Math.PI * 2); ctx.stroke();
  // Nan hoa
  ctx.beginPath();
  ctx.moveTo(-14, by - 4); ctx.lineTo(-24, by - 14);
  ctx.moveTo(14,  by - 4); ctx.lineTo(24,  by - 14);
  ctx.moveTo(-14, by + 24); ctx.lineTo(-22, by + 32);
  ctx.moveTo(14,  by + 24); ctx.lineTo(22,  by + 32);
  ctx.stroke();
  // Ngọc lục bảo
  ctx.fillStyle = '#10b981';
  [-16, 16].forEach(x => {
    ctx.beginPath(); ctx.arc(x, by - 6, 3, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(x, by + 24, 3, 0, Math.PI * 2); ctx.fill();
  });

  // 3. Đuôi trắng
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(12, by + 14); ctx.lineTo(32, by + 4); ctx.lineTo(18, by + 20); ctx.fill();

  // 4. Thân & Ngực
  ctx.beginPath(); ctx.ellipse(0, by + 10, 16 * sX, 12 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#334155';
  ctx.beginPath(); ctx.roundRect(-7, by + 4, 14, 12, 3); ctx.fill();

  // 5. 4 Chân & Móng vàng
  ctx.fillStyle = '#e2e8f0';
  [-14, -5, 3, 11].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 18, 5, 18, 2); ctx.fill();
  });
  ctx.fillStyle = '#facc15';
  [-15, -6, 2, 10].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 34, 7, 5, 2); ctx.fill();
  });

  // 6. Cổ cao
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(-6, by + 7); ctx.lineTo(4, by + 7); ctx.lineTo(0, by - 13); ctx.fill();
  ctx.strokeStyle = '#334155'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(-1, by + 6); ctx.lineTo(-1, by - 10); ctx.stroke();

  // 7. Đầu & Bờm
  ctx.fillStyle = '#334155';
  ctx.beginPath(); ctx.moveTo(-2, by - 14); ctx.lineTo(16, by - 38); ctx.lineTo(4, by - 14); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.moveTo(-6, by - 16); ctx.lineTo(18, by - 36); ctx.lineTo(0, by - 24); ctx.fill();
  ctx.beginPath(); ctx.ellipse(-6, by - 18, 9, 8, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.moveTo(-12, by - 18); ctx.lineTo(-8, by - 24); ctx.lineTo(-7, by - 16); ctx.fill();

  // 8. Mắt ngọc
  if (!blink) {
    ctx.fillStyle = '#22c55e';
    ctx.beginPath(); ctx.ellipse(-6, by - 18, 2, 3.5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-7, by - 19, 1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#334155'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-8, by - 18); ctx.lineTo(-4, by - 18); ctx.stroke();
  }

  ctx.restore();
}
